/**
 * withOwwabNative
 *
 * The `android/` folder is git-ignored and regenerated by `expo prebuild` (EAS does
 * this on every build). Anything hand-written inside it is lost. This plugin re-injects
 * the app's own native code at prebuild time from `native/android`:
 *
 *   - AzanModule / AzanReceiver / AzanService / BootReceiver  (exact-alarm adhan)
 *   - OemBatteryModule                                           (battery-killer helpers)
 *   - PrayerWidgetProvider + layout/xml resources                (home-screen widget)
 *
 * It also registers the packages in MainApplication, adds the manifest entries and
 * wires the "isAzanTriggered" intent handling into MainActivity.
 */
const {
  withDangerousMod,
  withAndroidManifest,
  withMainApplication,
  withMainActivity,
  AndroidConfig,
  withAndroidStyles,
  withGradleProperties,
} = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

const NATIVE_DIR = path.join(__dirname, '..', 'native', 'android');

function copyDirSync(src, dest) {
  if (!fs.existsSync(src)) return;
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) copyDirSync(from, to);
    else fs.copyFileSync(from, to);
  }
}

// ── 1. Copy Java/Kotlin sources and resources ───────────────────────────────
function withNativeSources(config) {
  return withDangerousMod(config, [
    'android',
    (config) => {
      const pkg = config.android.package;
      const projectRoot = config.modRequest.platformProjectRoot;
      const javaDest = path.join(projectRoot, 'app', 'src', 'main', 'java', ...pkg.split('.'));
      const resDest = path.join(projectRoot, 'app', 'src', 'main', 'res');

      // Sources declare `package com.mohamewael66sorganization.owwab`; rewrite if the
      // applicationId ever changes so the copied files still compile.
      const srcJava = path.join(NATIVE_DIR, 'java');
      const rewrite = (file, dest) => {
        let text = fs.readFileSync(file, 'utf8');
        text = text.replace(/com\.mohamewael66sorganization\.owwab/g, pkg);
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        fs.writeFileSync(dest, text);
      };
      const walk = (dir, rel = '') => {
        for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
          const from = path.join(dir, entry.name);
          const relPath = path.join(rel, entry.name);
          if (entry.isDirectory()) walk(from, relPath);
          else rewrite(from, path.join(javaDest, relPath));
        }
      };
      walk(srcJava);

      copyDirSync(path.join(NATIVE_DIR, 'res'), resDest);
      return config;
    },
  ]);
}

// ── 2. Manifest: services, receivers, widget provider ───────────────────────
function withNativeManifest(config) {
  return withAndroidManifest(config, (config) => {
    const manifest = config.modResults;
    const app = AndroidConfig.Manifest.getMainApplicationOrThrow(manifest);
    const pkg = config.android.package;

    app.service = app.service || [];
    app.receiver = app.receiver || [];

    const has = (list, name) => list.some((item) => item.$['android:name'] === name);

    if (!has(app.service, '.AzanService')) {
      app.service.push({
        $: {
          'android:name': '.AzanService',
          'android:foregroundServiceType': 'mediaPlayback',
          'android:exported': 'false',
        },
      });
    }

    if (!has(app.receiver, '.AzanReceiver')) {
      app.receiver.push({ $: { 'android:name': '.AzanReceiver', 'android:exported': 'false' } });
    }

    if (!has(app.receiver, '.BootReceiver')) {
      app.receiver.push({
        $: { 'android:name': '.BootReceiver', 'android:exported': 'true' },
        'intent-filter': [
          {
            $: { 'android:priority': '999' },
            action: [
              { $: { 'android:name': 'android.intent.action.BOOT_COMPLETED' } },
              { $: { 'android:name': 'android.intent.action.QUICKBOOT_POWERON' } },
              { $: { 'android:name': 'com.htc.intent.action.QUICKBOOT_POWERON' } },
              { $: { 'android:name': 'android.intent.action.MY_PACKAGE_REPLACED' } },
              { $: { 'android:name': 'android.intent.action.TIME_SET' } },
              { $: { 'android:name': 'android.intent.action.TIMEZONE_CHANGED' } },
            ],
            category: [{ $: { 'android:name': 'android.intent.category.DEFAULT' } }],
          },
        ],
      });
    }

    const widgetName = `${pkg}.widget.PrayerWidgetProvider`;
    if (!has(app.receiver, widgetName)) {
      app.receiver.push({
        $: { 'android:name': widgetName, 'android:exported': 'true' },
        'intent-filter': [
          {
            action: [
              { $: { 'android:name': 'android.appwidget.action.APPWIDGET_UPDATE' } },
              { $: { 'android:name': `${pkg}.ACTION_WIDGET_UPDATE` } },
            ],
          },
        ],
        'meta-data': [
          {
            $: {
              'android:name': 'android.appwidget.provider',
              'android:resource': '@xml/prayer_widget_info',
            },
          },
        ],
      });
    }

    return config;
  });
}

// ── 3. MainApplication: register packages ───────────────────────────────────
function withNativePackages(config) {
  return withMainApplication(config, (config) => {
    const pkg = config.android.package;
    let src = config.modResults.contents;
    const marker = '// add(MyReactNativePackage())';
    const lines = [
      `add(${pkg}.widget.PrayerWidgetPackage())`,
      `add(${pkg}.AzanPackage())`,
      `add(${pkg}.OemBatteryPackage())`,
      // Expo's autolinking leaves onnxruntime-react-native out of PackageList (its gradle
      // project is still built), so the recitation model's native module is added here
      'add(ai.onnxruntime.reactnative.OnnxruntimePackage())',
    ];
    const missing = lines.filter((l) => !src.includes(l));
    if (missing.length) {
      src = src.replace(marker, `${marker}\n              ${missing.join('\n              ')}`);
    }
    config.modResults.contents = src;
    return config;
  });
}

// ── 4. MainActivity: forward the adhan intent to JS ─────────────────────────
function withAzanIntent(config) {
  return withMainActivity(config, (config) => {
    let src = config.modResults.contents;
    if (src.includes('checkAzanIntent')) {
      config.modResults.contents = src;
      return config;
    }

    if (!src.includes('import android.view.WindowManager')) {
      src = src.replace('import android.os.Bundle', 'import android.os.Bundle\nimport android.view.WindowManager');
    }

    // Wake the screen and show over the keyguard only when the adhan launches the activity;
    // AzanModule.releaseLockScreen() undoes it when the azan screen closes.
    const wakeScreenCode = `    applyAzanWindow(intent)
    super.onCreate(null)
    checkAzanIntent(intent)`;

    src = src.replace('    super.onCreate(null)', wakeScreenCode);

    const helpers = `
  override fun onNewIntent(intent: android.content.Intent) {
    super.onNewIntent(intent)
    setIntent(intent)
    applyAzanWindow(intent)
    checkAzanIntent(intent)
  }

  /** Over the lock screen, screen on, kept on: like an alarm clock, for the adhan only. */
  private fun applyAzanWindow(intent: android.content.Intent?) {
    if (intent?.getBooleanExtra("isAzanTriggered", false) != true) return
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O_MR1) {
      setShowWhenLocked(true)
      setTurnScreenOn(true)
    } else {
      window.addFlags(
        WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED or
        WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON
      )
    }
    window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
  }

  private fun checkAzanIntent(intent: android.content.Intent?) {
    if (intent?.getBooleanExtra("isAzanTriggered", false) == true) {
      val prayerName = intent.getStringExtra("prayerName") ?: "الصلاة"
      AzanModule.setPendingAzan(prayerName)
      val params = com.facebook.react.bridge.Arguments.createMap()
      params.putString("prayerName", prayerName)
      reactContext?.getJSModule(com.facebook.react.modules.core.DeviceEventManagerModule.RCTDeviceEventEmitter::class.java)
        ?.emit("onAzanTriggered", params)
    }
  }

  // New Architecture (bridgeless) exposes the context through ReactHost; the legacy
  // reactInstanceManager getter throws "Cannot get ReactInstanceManager without a ReactNativeHost".
  private val reactContext: com.facebook.react.bridge.ReactContext?
    get() {
      val app = application as? com.facebook.react.ReactApplication ?: return null
      val fromHost = try { app.reactHost?.currentReactContext } catch (e: Exception) { null }
      if (fromHost != null) return fromHost
      return try { app.reactNativeHost.reactInstanceManager.currentReactContext } catch (e: Exception) { null }
    }

  /**
   * Returns the name of the main component registered from JavaScript.`;

    src = src.replace(
      '\n  /**\n   * Returns the name of the main component registered from JavaScript.',
      helpers
    );

    if (!src.includes('import android.os.Build')) {
      src = src.replace('import android.os.Bundle', 'import android.os.Build\nimport android.os.Bundle');
    }

    config.modResults.contents = src;
    return config;
  });
}

/**
 * The app theme has no window background, so Android paints its default grey for a
 * moment between the system splash and the first React frame. Make it the app's dark.
 */
function withDarkWindowBackground(config) {
  return withAndroidStyles(config, (cfg) => {
    const theme = cfg.modResults.resources.style?.find((st) => st.$.name === 'AppTheme');
    if (theme) {
      theme.item = (theme.item || []).filter((i) => i.$.name !== 'android:windowBackground');
      theme.item.push({ $: { name: 'android:windowBackground' }, _: '#0c0805' });
    }
    return cfg;
  });
}

/**
 * Default release builds to real phones only (arm64 + armv7). The emulator's x86_64
 * libraries are ~18 MB per ABI no phone uses; build them on demand with
 * -PreactNativeArchitectures=x86_64 (npm run apk:emu).
 */
function withPhoneArchitectures(config) {
  return withGradleProperties(config, (cfg) => {
    cfg.modResults = cfg.modResults.filter((p) => !(p.type === 'property' && p.key === 'reactNativeArchitectures'));
    cfg.modResults.push({ type: 'property', key: 'reactNativeArchitectures', value: 'armeabi-v7a,arm64-v8a' });
    return cfg;
  });
}

module.exports = function withOwwabNative(config) {
  config = withNativeSources(config);
  config = withNativeManifest(config);
  config = withNativePackages(config);
  config = withAzanIntent(config);
  config = withDarkWindowBackground(config);
  config = withPhoneArchitectures(config);
  return config;
};
